#!/usr/bin/env python3
"""Decisiones del «mundo vivo» y del vestuario (bloque 3, paridad con el fútbol). Cada texto va en 5 idiomas:
(es, en, fr, de, it); es/en entran en el evento y fr/de/it se registran en tools/i18n por la frase inglesa."""
import json, pathlib
ROOT = pathlib.Path(__file__).resolve().parent.parent
TR = {}

def register(ev, O, U):
    def t2(x):
        TR[x[1]] = x[2:5]
        return (x[0], x[1])
    def o(lab, fx, res): return O(t2(lab), ('', ''), fx, t2(res))
    def u(lab, p, okfx, ok, kofx, ko): return U(t2(lab), ('', ''), p, okfx, t2(ok), kofx, t2(ko))
    def E(eid, cat, mode, title, body, opts, once=False, **cond):
        ev(eid, cat, mode, t2(title), t2(body), opts, cond=cond, once=once)
    P, C, A = 'player', 'coach', 'any'

    # ---------- Torneo de verano ----------
